code.source:
#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

int main() {
    Student s;
    s.name = "Asha";
    s.marks = 91;
    cout << s.name << " scored " << s.marks << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

void show(const Student& s) {
    cout << s.name << ": " << s.marks << endl;
}

int main() {
    Student a = {"Asha", 91};
    Student b = {"Ravi", 78};
    show(a);
    show(b);
    return 0;
}

